IMAGE_FORMATS = {'.png', '.jpg'}
def upload_image(file):
    if file.suffix.lower() not in IMAGE_FORMATS:
        raise HTTPException(415, 'Unsupported image format')
    return save_image(file)

def ask(request):
    user = require_login(request)
    question = validate_question(request.json['question'])
    return service.answer(user.workspace, question)

def answer(workspace, question):
    sources = search(workspace, question)
    if not sources:
        return {'answer': None, 'missing': 'No matching evidence'}
    draft = model.generate(question, sources)
    validate_citation_ids(draft, sources)
    return draft

MAX_RETRIES = 3
def retry_job(job):
    if job.attempts >= MAX_RETRIES:
        return 'failed'
    return enqueue(job)
